 *
 * @param string $articleTitle The title of the Wikipedia article.
 * @return int The size of the lead section in characters.
 */
public function getLeadSectionSize($articleTitle) {
    $pageIdentity = PageIdentity::newFromTitle($articleTitle);
    $wikiPage = $this->getServiceContainer()->getWikiPageFactory()->newFromPageIdentity($pageIdentity);
    $content = $wikiPage->getContent();
    if ($content instanceof TextContent) {
        $sections = $content->getSections();
        if (!empty($sections)) {
            return strlen($sections[0]);
        }
    }
    return 0;
}
