/**
 * Fetches the size of a given Wikipedia section (in characters of wikitext).
 *
 * @param string $title The title of the Wikipedia article.
 * @return int The size of the lead section in characters.
 */
public function getLeadSectionSize(string $title): int {
    // Fetch the lead section content from the Wikipedia API
    $apiUrl = "https://en.wikipedia.org/w/api.php?action=query&prop=extracts&format=json&exintro=1&explaintext=1&titles=" . urlencode($title);
    $response = file_get_contents($apiUrl);
    $data = json_decode($response, true);

    // Extract the lead section content
    $pages = $data['query']['pages'];
    $pageId = array_key_exists('1', $pages) ? '1' : key($pages);
    $leadSectionContent = $pages[$pageId]['extract'];

    // Return the size of the lead section in characters
    return mb_strlen($leadSectionContent, 'UTF-8');
}
