 * system.
 *
 * Beta mode will be refactored properly in T212802, for now we need an easy way to retrieve
 * information about beta mode.
 *
 * IMPORTANT: This class provides read-only state, if you want to enable/disable beta mode
 * please use MobileContext classes.
 *
 * @since 1.44
 */
class BetaModeBridge {
    /**
     * @var bool
     */
    private $isBetaModeEnabled;

    /**
     * Constructor to initialize the beta mode state.
     *
     * @param bool $isBetaModeEnabled Whether beta mode is enabled.
     */
    public function __construct(bool $isBetaModeEnabled) {
        $this->isBetaModeEnabled = $isBetaModeEnabled;
    }

    /**
     * Checks if beta mode is enabled.
     *
     * @return bool True if beta mode is enabled, false otherwise.
     */
    public function isBetaModeEnabled(): bool {
        return $this->isBetaModeEnabled;
    }
}
